const app=document.querySelector('#app'),homeHTML=app.innerHTML,KEY='uruguay-compass-v2',OLD_KEY='uruguay-compass-v1',ARCHIVE_KEY='uruguay-compass-v1-archive',AUDIT_ARCHIVE='uruguay-compass-v2-archive';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
let state=null,storageOK=true,theme='light',selectedVersion='short',autoAdvance=false;
const spectrumState={query:'',party:'all',selectedId:null};
const rankingCount=FIGURES.filter(f=>f.rankEligible).length;
const comparatorChoices=comparisonEntities(FIGURES,PARTIES),comparatorState={ids:[]};
let stopResultTracking=()=>{},pendingAuditArchive=null;
function archiveAuditedState(raw){const previous=localStorage.getItem(AUDIT_ARCHIVE);let archives=[];if(previous!==null){try{const parsed=JSON.parse(previous);archives=Array.isArray(parsed)&&parsed.every(x=>typeof x==='string')?parsed:[previous]}catch{archives=[previous]}}if(!archives.includes(raw))archives.push(raw);localStorage.setItem(AUDIT_ARCHIVE,JSON.stringify(archives));pendingAuditArchive=null}
try{const saved=localStorage.getItem(KEY),previous=saved===null?localStorage.getItem(OLD_KEY):null;state=restoreState(saved??previous,QUESTIONS);if(saved&&state&&JSON.parse(saved).schema===2){pendingAuditArchive=saved;archiveAuditedState(saved);localStorage.setItem(KEY,JSON.stringify(state))}if(previous&&state){const archived=localStorage.getItem(ARCHIVE_KEY);if(archived===null)localStorage.setItem(ARCHIVE_KEY,previous);localStorage.setItem(KEY,JSON.stringify(state));if(archived===null||archived===previous)localStorage.removeItem(OLD_KEY)}theme=localStorage.getItem('compass-theme')==='dark'?'dark':'light';autoAdvance=localStorage.getItem('compass-auto-advance')==='true'}catch{storageOK=false}
document.documentElement.dataset.theme=theme;
syncThemeColor();
const announce=t=>{document.querySelector('#announcement').textContent=t};
function save(){try{if(pendingAuditArchive)archiveAuditedState(pendingAuditArchive);localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false;announce('No se pudo guardar. Podés seguir, pero el avance se pierde al cerrar.')}}
function go(route){if(location.hash===`#${route}`)render();else location.hash=route}
function profile(){return state&&isComplete(questionSet(QUESTIONS,state.version),state.answers)?scoreProfile(questionSet(QUESTIONS,state.version),state.answers):null}
const sourceList=s=>`<ul class="sources">${(s||[]).map(x=>`<li>${link(x.url,x.title)}</li>`).join('')}</ul>`;
function portrait(e){const p=PHOTOS[e.id];return p?`<figure class="portrait">${p.crop?`<span class="portrait-window" style="${portraitStyle(p)}">`:""}<img src="${esc(p.src)}" alt="Retrato de ${esc(e.name)}" width="200" height="240" loading="lazy">${p.crop?"</span>":""}</figure>`:e.photoUnavailable?`<figure class="portrait portrait-placeholder"><div aria-hidden="true">${esc(e.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div></figure>`:''}
const secondary=(a,t)=>`<button class="secondary" data-action="${a}">${t}</button>`;
const themeGraphic=()=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${theme==='dark'?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>':'<path d="M20.5 14A9 9 0 0 1 10 3.5 9 9 0 1 0 20.5 14Z"/>'}</svg>`;
const themeButton=()=>`<button type="button" class="icon-button" data-action="theme" aria-label="${theme==='dark'?'Activar modo claro':'Activar modo oscuro'}" title="${theme==='dark'?'Activar modo claro':'Activar modo oscuro'}">${themeGraphic()}</button>`;
function header(test=false){return `<header class="app-header"><a class="app-brand" href="#inicio"><img src="sun.svg" width="36" height="36" alt=""><strong>Uruguay Compass</strong></a><nav aria-label="${test?'Controles del test':'Principal'}"${test?' class="test-header-controls"':''}>${test?themeButton()+`<button type="button" class="icon-button" data-action="reset" aria-label="Reiniciar el test" title="Reiniciar el test"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/></svg></button>`:'<a class="nav-button" href="#enciclopedia">Enciclopedia</a><a class="nav-button" href="#comparador">Comparador</a><a class="nav-button" href="#metodologia">Metodología</a><a class="nav-button" href="#faq">Ayuda</a>'+themeButton()}</nav></header>`}
function shell(title,body,wide=false,test=false){stopResultTracking();app.innerHTML=header(test)+`<main id="main" class="page ${wide?'wide':''}" tabindex="-1"><h1>${title}</h1>${body}</main><footer class="app-footer"><span>Educativo. Sin validación científica ni recomendación de voto.</span><a class="nav-button" href="#correcciones">Señalar un error</a><a href="#privacidad">Privacidad</a></footer>`}
function renderHome(){stopResultTracking();app.innerHTML=homeHTML;app.querySelector('.home-header').insertAdjacentHTML('beforeend',themeButton());app.querySelector('#home-title').innerHTML='¿A qué personaje político<br class="desktop-br"> se acercan <span>tus ideas?</span>';const footer=app.querySelector('.home-footer');footer.insertAdjacentHTML('beforeend',`<div class="home-tools"><a class="nav-button" href="#faq">Ayuda</a><a class="nav-button" href="#correcciones">Señalar un error</a></div>`);if(state?.migrated)app.querySelector('.home-intro').insertAdjacentHTML('beforeend','<p class="notice">El test anterior se conserva. Mantuvimos las respuestas sin cambios; completá únicamente las preguntas nuevas pendientes.</p>');if(state)app.querySelector('.home-intro').insertAdjacentHTML('beforeend',`<div class="resume-actions"><a class="secondary" href="#${state.completed?'resultados':'test'}">${state.completed?'Ver mi resultado guardado':'Continuar mi test'}</a>${secondary('reset','Empezar de nuevo')}</div>`);drawRadar(document.querySelector('#home-radar'),[70,48,58,54,44,56,68,75,57,72,63,48]);}
const answerLabels=['Muy en desacuerdo','En desacuerdo','Ni de acuerdo ni en desacuerdo','De acuerdo','Muy de acuerdo'];
function startScreen(){if(state){go(state.completed?'resultados':'test');return}shell('Elegí la duración del test',`<fieldset class="version-choice"><legend class="sr-only">Versiones del test</legend>${Object.entries(VERSIONS).map(([id,v])=>`<label><input type="radio" name="version" value="${id}" ${id===selectedVersion?'checked':''}><span><strong>${v.label}</strong> · ${v.count} preguntas · ${v.minutes} min</span></label>`).join('')}</fieldset><div class="actions"><button class="primary" data-action="start">Empezar el test</button><a href="#inicio">Volver al inicio</a></div>`);document.querySelector('#main').classList.add('test-start-page')}

function testScreen(){
 if(!state){go('inicio');return}if(state.completed){go('resultados');return}
 const qs=questionSet(QUESTIONS,state.version),q=qs[state.cursor],v=state.answers[q.id],axis=AXES[q.axis],answered=Object.keys(state.answers).length,percent=Math.round(answered/qs.length*100);
 shell('Tus ideas, pregunta a pregunta',`
 <div class="test-top"><span>Pregunta <strong>${state.cursor+1} de ${qs.length}</strong></span><span>${percent}% completado</span></div>
 <progress class="sr-only" value="${answered}" max="${qs.length}" aria-label="Preguntas respondidas"></progress>
 <div class="question-progress" aria-hidden="true">${Array.from({length:12},(_,i)=>`<span><i style="width:${Math.max(0,Math.min(100,(answered/qs.length*12-i)*100))}%"></i></span>`).join('')}</div>
 <form id="question-form" autocomplete="off">
 <section class="question-card" aria-label="Pregunta actual">
 <span class="question-number" aria-hidden="true">${String(state.cursor+1).padStart(2,'0')}</span>
 <div class="question-meta"><span class="question-axis" data-axis="${axis.slug}" aria-label="Eje: ${esc(axis.name)}">${quizIcon(axis.slug)}${esc(axis.name)}</span><button type="button" class="question-help" data-action="question-context" aria-expanded="false" aria-controls="question-context">${quizIcon('help')}Entender</button></div>
 <div id="question-context" class="question-context" hidden><p>${esc(axis.description)}</p><a href="#eje/${q.axis}">Leer ambas posturas y volver al test</a></div>
 <fieldset><legend class="question">${esc(q.text)}</legend><div class="answers">${[0,1,2,3,4].map(i=>`<label class="answer answer-${i>2?'agree':i<2?'disagree':'neutral'}"><span class="answer-symbol" aria-hidden="true">${quizIcon(i>2?'agree':i<2?'disagree':'neutral')}</span><span class="answer-label">${answerLabels[i]}</span><input type="radio" name="answer" value="${i}" ${v===i?'checked':''}></label>`).join('')}</div></fieldset>
 </section>
 <div class="test-controls"><button type="button" class="secondary" data-action="previous" ${state.cursor===0?'disabled':''}>${quizIcon('back')}Anterior</button><div class="test-options"><button type="button" class="auto-advance" data-action="auto-advance" aria-pressed="${autoAdvance}"><span class="auto-switch" aria-hidden="true"></span><span>Avance automático</span><strong class="sr-only">${autoAdvance?'Activado':'Desactivado'}</strong></button></div><button class="primary" type="submit" ${!validAnswer(v)?'disabled':''}>${state.cursor===qs.length-1?'Ver mi resultado':'Siguiente'}${quizIcon('next')}</button></div>
 </form>
 <p class="small muted test-storage">${storageOK?'Tu avance se guarda solo en este navegador.':'El almacenamiento está bloqueado. Podés seguir, pero no cerrar esta página.'} Podés volver y cambiar cualquier respuesta.</p><a class="quiet-link" href="#inicio">Salir y conservar avance</a>`,false,true);
 document.querySelectorAll('#question-form input[name=answer]').forEach(input=>{input.checked=validAnswer(v)&&Number(input.value)===v});
 document.querySelector('#main').classList.add('questionnaire-page');document.querySelector('#main>h1').classList.add('sr-only');
}
const ranked=()=>rankFigures(profile(),FIGURES);
const rankingTie=r=>r.closest.length>1?`<p class="small">Empate exacto de afinidad: ${r.closest.map(x=>esc(x.entity.name)).join(' · ')}. Se destaca automáticamente el primero en orden alfabético; no indica mayor cercanía. Los programas compartidos pueden producir perfiles idénticos; las fuentes individuales se conservan.</p>`:'';
const resultScore=(score,label='afinidad estimada')=>`<strong class="match-score">${score}%<span>${esc(label)}</span></strong>`;
function matchRow(x){if(!x)return '';const e=x.entity,photo=portrait(e),context=e.partyName?[...new Set([e.partyName,e.era].filter(Boolean))].join(' · '):e.period||e.era||'';return `<article class="match-row${photo?' match-row--portrait':''}">${photo}<div class="match-copy"><h3><a href="#${e.id.startsWith('partido-')?'partido/'+e.id.slice(8):'ficha/'+e.id}">${esc(e.name)}</a></h3>${e.partyName?renderPersonDetails(e):`<p class="small">${esc(context)}</p><p>${esc(e.summary)}</p>`}<p class="small match-inference">${esc(inferenceSummary(e))}</p></div>${resultScore(x.score)}</article>`}
function resultsDashboard(){
 const p=profile();if(!p){shell('Todavía falta tu perfil',`<p>Completá las preguntas para ver tus doce posiciones.</p><a class="primary button-link" href="#${state?'test':'inicio'}">${state?'Continuar':'Elegir un test'}</a>`);return}
 const qs=questionSet(QUESTIONS,state.version),r=ranked(),lead=r.ranked[0],models=readingModels(p),model=ideologyDescription(models[0]),partyRanking=rankParties(p,PARTIES).ranked,diff=comparisonDetails(p,lead.entity.profile,r.axes),compassReading=describeCompass(p[0],p[3]);
 const sections=[['ideology-panel','Tu ideología'],['axes-panel','Doce ejes'],['figures-panel','Personajes'],['priorities-panel','Lo que te distingue'],['parties-panel','Partidos'],['differences-panel','Coincidencias y diferencias'],['compass-panel','Brújula política'],['share-panel','Tu tarjeta']];
 const partyRow=({entity,score},featured=false)=>{
  const {id,name}=entity;
  const flagClass=id==='is'?'party-match-flag party-match-emblem':'party-match-flag';
  return `<article class="party-match${featured?' party-match-featured':''}">
   <img class="${flagClass}" src="${PARTY_FLAGS[id].src}" alt="" loading="lazy">
   <div class="party-match-copy">
    <h4><a href="#partido/${id}">${esc(name)}</a></h4>
    ${featured?'<span class="party-match-lead-label">Partido principal</span>':''}
    <a class="match-more" href="#comparar/partido-${id}">Comparar conmigo</a>
   </div>
   ${resultScore(score)}
  </article>`;
 };
 shell('Tu perfil ideológico',`<p class="results-intro">${VERSIONS[state.version].label} · ${qs.length} respuestas · Doce dimensiones de tus ideas.</p><p class="small ranking-coverage">Comparación estimada con ${rankingCount} referentes sobre doce ejes; incluye hipótesis identificadas.</p><div class="results-layout"><div class="results-content">
 <section class="result-panel ideology-profile" id="ideology-panel"><div class="ideology-heading"><div><p class="small">La ideología que mejor describe estas respuestas</p><h2>${esc(model.name)}</h2></div>${resultScore(model.score,'similitud')}</div><div class="ideology-phrase"><h3>Una frase que te describe</h3><p>"${esc(model.phrase)}"</p></div><details><summary>+ Sobre ${esc(model.name)}</summary><p>${esc(model.text)}</p><p>Es el más cercano entre cinco modelos pedagógicos propios, sobre economía, impuestos, trabajo y valores sociales. No es una identidad definitiva ni una recomendación de voto.</p><p>Similitud = 100 menos la distancia absoluta media. Modelo: ${MODEL_AXES.map((i,j)=>esc(AXES[i].name)+': '+models[0].values[j]).join(' · ')}.</p>${models.filter(m=>m.score===model.score).length>1?'<p>Empate con '+models.filter(m=>m.score===model.score&&m.id!==model.id).map(m=>esc(ideologyDescription(m).name)).join(', ')+'. El orden es convencional.</p>':''}</details></section>
  <section class="result-panel" id="axes-panel"><h2>Tus doce ejes</h2><div class="axes-grid">${AXES.map((a,i)=>`<article class="axis-tile">${renderAxisSummary(a,p[i])}</article>`).join('')}</div></section>
 <section class="result-panel figure-matches" id="figures-panel"><h2>Coincidencias con personajes</h2><article class="figure-lead"><div class="closest-person"><h3>Mayor afinidad estimada</h3>${portrait(lead.entity)}<h4>${esc(lead.entity.name)}</h4>${renderPersonDetails(lead.entity)}${resultScore(lead.score)}<p class="small">Afinidad sobre doce ejes; es una comparación distinta de la ideología. ${esc(inferenceSummary(lead.entity))}</p>${rankingTie(r)}<a href="#ficha/${lead.entity.id}">+ Más sobre ${esc(lead.entity.name)}</a></div></article><h3>También cerca de vos</h3><div class="figure-nearby">${r.ranked.slice(1,4).map(matchRow).join('')}</div><h3>Las referencias más alejadas</h3><div class="far-figures">${r.ranked.slice(-2).reverse().map(matchRow).join('')}</div><p class="small">Afinidad editorial sobre los doce ejes. Las hipótesis pueden cambiar el orden de cercanía; no son opiniones comprobadas. Los empates exactos no se fuerzan para crear diferencias.</p><a href="#comparaciones">Ver todas las comparaciones</a></section>
 <section class="result-panel" id="priorities-panel"><h2>Lo que te distingue</h2>${distinctivePriorities(p,FIGURES)}</section>
 <section class="result-panel" id="parties-panel">
  <h2>Afinidad con partidos</h2>
  <div class="party-match-group"><h3>Los tres más cercanos</h3>${partyRow(partyRanking[0],true)}${partyRanking.slice(1,3).map(match=>partyRow(match)).join('')}</div>
  <div class="party-match-group"><h3>Los dos más alejados</h3>${partyRanking.slice(-2).reverse().map(match=>partyRow(match)).join('')}</div>
 </section>
 <section class="result-panel" id="differences-panel"><h2>Coincidencias y diferencias</h2><label class="comparison-select"><span>Elegí un político para comparar</span><select id="insight-reference">${r.ranked.map(x=>`<option value="${x.entity.id}" ${x.entity.id===lead.entity.id?'selected':''}>${esc(x.entity.name)}</option>`).join('')}</select></label><div id="difference-content">${renderDifferences(lead.entity,diff)}</div></section>
 <section class="result-panel compass-panel" id="compass-panel"><h2>Tu brújula política</h2><div class="political-grid-layout">${renderPoliticalGrid(p)}<div><h3>${esc(compassReading.title)}</h3><p>${esc(compassReading.text)}</p>${renderAxisSummary(AXES[5],p[5])}</div></div><p class="small">Proyección de economía y seguridad; no mide autoritarismo ni resume los doce ejes.</p><details><summary>Explorar el mapa con los ${rankingCount} referentes</summary>${renderSpectrum(p,FIGURES.filter(f=>f.rankEligible),{...spectrumState,selectedId:spectrumState.selectedId||lead.entity.id})}</details></section>
  <section class="result-panel" id="share-panel"><h2>Tu tarjeta de resultados</h2><p>Una síntesis visual con tu referencia más cercana, su foto, las otras coincidencias y los doce ejes. Se genera en este dispositivo.</p>${renderResultPoster({profile:p,axes:AXES,ranking:r.ranked,photos:PHOTOS})}<div class="actions">${secondary('download','Guardar imagen PNG')}${secondary('share','Compartir imagen')}${secondary('reset','Repetir el test')}${secondary('privacy','Borrar mis datos')}</div><p id="export-status" role="status"></p><canvas id="share-preview" class="share-preview" width="1200" height="1500" hidden aria-label="Vista previa de la imagen generada"></canvas><p class="small">Educativo. Sin validación científica ni recomendación de voto.</p></section>
 </div><aside class="results-index"><nav aria-label="Secciones de mi resultado"><h2>Tu resultado</h2>${sections.map(([id,title])=>`<a href="#resultados" data-jump="${id}">${title}</a>`).join('')}</nav><a href="#metodologia">Método y límites</a></aside></div>`,true);
 document.querySelector('#main').classList.add('results-page');stopResultTracking=trackResultSection(document.querySelector('#main'));
}
function compareScreen(id){const p=profile(),e=[...FIGURES,...PARTIES.map(x=>({...x,id:'partido-'+x.id}))].find(x=>x.id===id);if(!p||!e){shell('Comparación no disponible','<p>Necesitás completar el test y elegir una ficha válida.</p><a href="#resultados">Ir a resultados</a>');return}if(e.researchOnly){shell(esc(e.name),`<p class="notice">${esc(e.comparisonNote)}</p>${renderPersonDetails(e)}${renderDocumentaryProfile(e)}<a href="#ficha/${e.id}">Ver ficha completa</a><br><a href="#resultados">Volver a mi resultado</a>`);return}const common=ranked().axes;shell(`Tus respuestas y ${esc(e.name)}`,`<p>${esc(e.comparisonNote)}</p><p class="notice">Puntajes editoriales de 0 (polo izquierdo) a 100 (derecho). «Sin evidencia» no equivale a 50. Solo los ejes marcados como comunes intervienen en el ranking.</p><div class="table-scroll"><table><caption>Comparación por eje</caption><thead><tr><th>Eje y polos</th><th>Vos</th><th>Referencia</th><th>Fundamento y fuente</th></tr></thead><tbody>${AXES.map((a,i)=>{const ev=e.evidence?.find(v=>v.axis===i),s=ev&&e.sources[ev.source];return `<tr><th>${esc(a.name)}${common.includes(i)?'<small>Común al ranking</small>':''}<small>${esc(a.left)} → ${esc(a.right)}</small></th><td>${p[i]}</td><td>${e.profile[i]===null?'Sin evidencia':e.profile[i]}</td><td>${esc(e.rationale[i])}${s?`<br>${link(s.url,`${s.title}${ev.page?' · p. '+ev.page:''}`)}`:''}</td></tr>`}).join('')}</tbody></table></div><a href="#resultados">Volver a mi resultado</a>`,true)}
function comparisons(){const p=profile();if(!p){go('resultados');return}const a=ranked(),b=rankParties(p,PARTIES.map(x=>({...x,id:'partido-'+x.id})));shell('Todas las comparaciones',`<p>Las candidaturas y los partidos pueden coincidir en porcentaje porque se usa el mismo programa como referencia. No es una estimación independiente de cada persona.</p><h2>Candidaturas de distintas elecciones</h2><p>${rankingCount} referentes de distintas etapas, comparados sobre los mismos doce ejes, con hipótesis identificadas. Los períodos anteriores describen sus programas de entonces; no sus posturas actuales.</p>${a.ranked.map(matchRow).join('')}<h2>Partidos con representación parlamentaria</h2><p class="small">Referencia: programas 2025–2030 y composición parlamentaria al inicio de la legislatura. Fuentes en cada ficha.</p>${b.ranked.map(matchRow).join('')}<a href="#resultados">Volver al resultado</a>`,true)}
function comparatorScreen(routeIds){if(routeIds!==undefined)comparatorState.ids=selectedComparisonProfiles(comparatorChoices,comparisonIdsFromRoute(routeIds)).map(item=>item.id);shell('Lado a lado, en los doce ejes',renderComparator(comparatorChoices,comparatorState.ids),true);const root=document.querySelector('#main');root.classList.add('comparator-page');stopResultTracking=mountComparator(root,comparatorChoices,comparatorState.ids,ids=>{comparatorState.ids=ids;window.history.replaceState(null,'',comparisonShareHash(ids));comparatorScreen();const target=document.querySelector('#compare-search')||document.querySelector('#cmp-profiles h2');target?.focus({preventScroll:true})})}
function encyclopedia(){shell('Los doce ejes',`<p class="lead">Doce temas para explorar tus ideas. Cada eje compara dos posturas; ninguno resume por sí solo tu identidad política.</p><nav class="section-nav" aria-label="Secciones de la enciclopedia"><a class="nav-button" href="#figuras">Personajes</a><a class="nav-button" href="#partidos">Partidos</a><a class="nav-button" href="#glosario">Glosario</a><a class="nav-button" href="#historia">Historia</a></nav><div class="axis-guide-grid">${AXES.map(a=>`<a class="axis-guide-card" href="#eje/${a.id}"><h2><span class="axis-guide-number">${String(a.id+1).padStart(2,'0')}</span>${esc(a.name)}</h2><p class="axis-guide-poles"><span><span aria-hidden="true">${a.leftIcon}</span> ${esc(a.left)}</span><span aria-hidden="true">↔</span><span>${esc(a.right)} <span aria-hidden="true">${a.rightIcon}</span></span></p><p>${esc(a.description)}</p><span class="sr-only">Leer posturas, debates y fuentes</span></a>`).join('')}</div>`,true);document.querySelector('#main').classList.add('axis-guide-page')}

function axisScreen(id){const a=AXES[Number(id)];if(!a){notFound();return}shell(esc(a.name),`<p class="lead">${esc(a.description)}</p><div class="two-poles"><section><h2>${esc(a.left)}</h2><p>${esc(a.leftText)}</p></section><section><h2>${esc(a.right)}</h2><p>${esc(a.rightText)}</p></section></div><h2>Debates en Uruguay</h2><ul>${a.debates.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Para consultar</h2>${sourceList(a.sources)}<div class="actions"><a href="#enciclopedia">Todos los ejes</a>${state&&!state.completed?'<a href="#test">Volver a mi pregunta</a>':''}</div>`)}
function entityList(kind){const party=kind==='partidos',es=[...(party?PARTIES:FIGURES)].sort((a,b)=>a.name.localeCompare(b.name,'es'));shell(party?'Partidos y sus propuestas':'Personajes y sus propuestas',`<p>${party?'Las fichas presentan el contexto y las fuentes. Una ubicación editorial no resume una trayectoria completa.':es.length+' fichas disponibles como resultado en doce ejes. Cada ficha distingue fuentes temáticas de hipótesis muy inciertas y conserva las fechas de sus antecedentes.'}</p><label class="search-label">Buscar por nombre<input type="search" id="entity-search" placeholder="Escribí un nombre" autocomplete="off"></label><div class="reading-list entity-directory" id="entity-list">${es.map(e=>`<a data-search="${esc((e.name+' '+(e.partyName||'')+' '+(e.aliases||[]).join(' ')).toLocaleLowerCase('es'))}" href="#${party?'partido':'ficha'}/${e.id}">${entityMedia(e,{party})}<div><strong>${esc(e.name)}${party?'':`<small class="entity-status">${e.rankEligible?'Disponible como resultado':'Ficha de contexto · fuera del cálculo'}</small>`}</strong>${party?`<span>${esc(e.period||e.era)} · ${esc(e.short||'')}</span>`:renderPersonDetails(e)}</div></a>`).join('')}</div><p id="search-empty" hidden>No hay coincidencias. Probá con otra palabra.</p>`)}

function entityScreen(id,party=false){
 const e=(party?PARTIES:FIGURES).find(x=>x.id===id);
 if(!e){notFound();return}
 const hasScores=e.profile.some(Number.isFinite);
 const axes=()=>`<h2>Ubicación y fundamentos</h2>${AXES.map((a,i)=>`<details><summary>${esc(a.name)} <span>${e.profile[i]===null?'Sin evidencia suficiente':e.profile[i]+' / 100'}</span></summary><p>${esc(a.left)} → ${esc(a.right)}</p><p>${esc(e.rationale[i])}</p>${(e.evidence||[]).filter(v=>v.axis===i).map(v=>{const s=e.sources[v.source];return s?`<p>${link(v.page?s.url.split('#')[0]+'#page='+v.page:s.url,`${s.title}${v.page?' · p. '+v.page:''}`)}</p>`:''}).join('')}</details>`).join('')}`;
 const comparison=e.axisResearch?renderDocumentaryProfile(e):e.historical?'':hasScores?axes():'<h2>Datos para comparar</h2><p>Las fuentes de esta ficha documentan su trayectoria. Todavía falta evidencia comparable para asignarle una posición en los ejes del test.</p>';
 shell(esc(e.name),`${portrait(e)}${party?`<p class="muted">${esc(e.period||e.era)} · ${esc(e.short||'')}</p>`:renderPersonDetails(e)}<p class="lead">${esc(e.bio||e.summary)}</p>${e.actions?.length?`<h2>Trayectoria y propuestas documentadas</h2><ul>${e.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="notice">${esc(e.comparisonNote)}${hasScores?' Las posturas pueden cambiar con el tiempo. Los números siguientes son estimaciones editoriales.':''}</p>${comparison}<h2>Fuentes públicas</h2>${sourceList(e.sources)}<div class="actions">${profile()&&hasScores?`<a class="secondary" href="#comparar/${party?'partido-':''}${e.id}">Comparar con mis respuestas</a>`:''}<a href="#correcciones">Proponer una corrección con fuentes</a><a href="#${party?'partidos':'figuras'}">Volver al índice</a></div>`);
}

function glossary(){shell('Glosario',`<p>Palabras políticas en contexto uruguayo, sin convertirlas en etiquetas para personas.</p><label class="search-label">Buscar un término<input id="glossary-search" type="search" placeholder="Por ejemplo, liberal o AFAP"></label><div id="glossary-list">${GLOSSARY.map(x=>`<article class="glossary-entry" data-search="${esc((x.term+' '+x.definition).toLocaleLowerCase('es'))}"><h2>${esc(x.term)}</h2><p>${esc(x.definition)}</p></article>`).join('')}</div><p id="search-empty" hidden>No encontramos ese término. Probá con otra palabra.</p>`)}
function history(){shell('Un recorrido por la historia política',`<p>Una selección de hitos para ubicar los debates en su época; no pretende agotar la historia del país.</p><ol class="timeline">${TIMELINE.map(t=>`<li><time>${esc(t.year)}</time><div><h2>${esc(t.title)}</h2><p>${esc(t.text)}</p>${link(t.source.url,t.source.title)}</div></li>`).join('')}</ol>`)}
function methodology(){shell('Método y límites',`<p>Herramienta educativa de reflexión política. No es una encuesta electoral, una validación científica ni una recomendación de voto.</p><h2>Preguntas y puntajes</h2><p>Las versiones conservan las mismas preguntas y el mismo cálculo: cada respuesta vale −2, −1, 0, 1 o 2; se invierte el signo cuando apunta al polo izquierdo. El puntaje por eje es 50 + 25 × media. Los doce ejes no se reducen a una etiqueta universal.</p><h2>Afinidad en doce ejes</h2><p>Personajes y partidos se comparan en los mismos doce ejes, todos con igual peso: <strong>100 − suma de las doce diferencias absolutas / 12</strong>. Es proximidad entre coordenadas editoriales, no probabilidad de votar ni certeza histórica. El orden usa la distancia antes de redondear el porcentaje; un empate exacto se conserva y se destaca el primer nombre alfabético.</p><h2>Fuentes e hipótesis</h2><p>Hay ${FIGURES.length} personas y seis partidos. Las fuentes temáticas proceden de programas, medidas y declaraciones fechadas. Las coordenadas son interpretaciones propias en pasos de cinco puntos, no cifras emitidas por las fuentes. Una ley promulgada no implica autoría exclusiva del presidente.</p><p>Cuando falta un antecedente sobre un tema, se incluye una <strong>hipótesis contrafáctica asistida por IA, de confianza muy baja</strong>, derivada del pensamiento y la trayectoria registrados. Sus referencias son contexto de la analogía: no prueban la posición inferida. No se afirma qué respondería una persona histórica hoy. Estos supuestos pueden cambiar el ranking; completar casillas no demuestra mayor precisión empírica.</p><p>Las fichas muestran las doce ubicaciones con fundamento, fechas y confianza. Los perfiles compuestos pueden combinar etapas diferentes. Se conservan diferencias entre dirigentes, incluso si pertenecen al mismo partido, y los empates reales de programas compartidos.</p><h2>Otros resultados</h2><p>La ideología usa cinco modelos pedagógicos sobre cuatro ejes; no se modificó su fórmula. Los países mantienen su comparación constitucional de tres ejes. Por eso sus porcentajes representan comparaciones distintas.</p><p>La brújula proyecta solamente economía y seguridad. En Lo que te distingue, las medianas se calculan con coordenadas que tienen fuente temática; las hipótesis no se convierten en evidencia de la mediana.</p><h2>Privacidad</h2><p>Las respuestas se procesan en este navegador. No se envían a una IA para calcular tu resultado. La investigación editorial asistida por IA es independiente de las respuestas de quienes hacen el test.</p><a href="#correcciones">Proponer una corrección con fuentes</a>`,true)}
function faq(){shell('Preguntas frecuentes',FAQ.map((f,i)=>`<details><summary>${esc(f.q)}</summary><p>${esc(i===FAQ.length-1?'Usá «Señalar un error» para preparar una observación con una fuente pública. Podés descargarla o abrir un borrador de Issue en GitHub. Solo se envía cuando vos lo publicás allí; GitHub puede pedir una cuenta.':f.a)}</p></details>`).join(''))}
function privacy(){shell('Tus respuestas quedan acá',`<p>El test procesa tus respuestas y calcula el resultado en tu navegador, sin cuentas propias ni envío de tus elecciones a servidores. El alojamiento recibe las solicitudes normales de archivos.</p><h2>Estadísticas de visitas</h2><p>Usamos Cloudflare Web Analytics para conocer las visitas y el rendimiento de la web. Su script envía métricas de navegación y carga a Cloudflare, sin cookies de seguimiento. No enviamos respuestas, puntajes, afinidades políticas ni eventos del cuestionario. La medición automática de cambios de pantalla está desactivada.</p><p>Podés consultar <a href="https://developers.cloudflare.com/web-analytics/about/" target="_blank" rel="noopener noreferrer">cómo funciona Cloudflare Web Analytics</a>.</p><p>El progreso se guarda en este navegador. Otras personas que usen el mismo perfil podrían verlo. El modo privado o las preferencias de almacenamiento pueden impedir que se conserve.</p><p>Las fuentes públicas y GitHub son servicios externos. Se abren solo cuando elegís sus enlaces. Los borradores de correcciones contienen únicamente lo que escribas en el formulario, nunca las respuestas del test.</p><h2>Borrar el avance y resultado</h2><p>Esta acción borra el test actual y las copias de ediciones anteriores guardadas en este navegador; no elimina las estadísticas generales de visitas.</p>${secondary('erase','Borrar mis respuestas')}<p id="erase-status" role="status"></p>`)}
function corrections(){shell('Ayudanos a corregir',`<p>Señalá un error o cuestioná una ubicación con fuentes. No incluyas datos personales ni tus respuestas del test.</p><form id="correction-form"><label>Pregunta, eje o personaje<input name="subject" required maxlength="160" placeholder="Por ejemplo: economía, pregunta sobre ANCAP"></label><label>Qué proponés corregir<textarea name="message" required minlength="15" maxlength="5000" rows="6"></textarea></label><label>Fuente pública (enlace HTTPS)<input name="source" type="url" pattern="https://.*" required maxlength="1500" placeholder="https://"></label><div class="actions"><button class="primary" type="submit">Preparar reporte</button></div></form><div id="correction-output" hidden><h2>Reporte preparado</h2><p>No se envió todavía. Revisalo y elegí si querés publicarlo en GitHub; puede requerir una cuenta.</p><pre id="correction-preview"></pre><div class="actions"><a class="secondary" id="issue-link" target="_blank" rel="noopener noreferrer">Abrir borrador en GitHub</a>${secondary('report-download','Descargar reporte TXT')}</div></div>`)}
function notFound(){shell('No encontramos esa página','<p>Volvé al inicio o explorá la enciclopedia.</p><a href="#inicio">Ir al inicio</a>')}
function render(){const [route,id]=location.hash.slice(1).split('/');const views={inicio:renderHome,iniciar:startScreen,test:testScreen,resultados:resultsDashboard,comparaciones:comparisons,comparador:()=>comparatorScreen(id),enciclopedia:encyclopedia,figuras:()=>entityList('figuras'),partidos:()=>entityList('partidos'),eje:()=>axisScreen(id),ficha:()=>entityScreen(id),partido:()=>entityScreen(id,true),comparar:()=>compareScreen(id),glosario:glossary,historia:history,metodologia:methodology,faq,privacidad:privacy,correcciones:corrections};(Object.hasOwn(views,route||'inicio')?views[route||'inicio']:notFound)();document.title=`${document.querySelector('h1')?.textContent||'Inicio'} · Uruguay Compass`;window.scrollTo(0,0);if(route&&route!=='inicio')document.querySelector('#main')?.focus({preventScroll:true})}
let reportText='';
document.addEventListener('click',async event=>{const jump=event.target.closest('[data-jump]');if(jump){event.preventDefault();const target=document.getElementById(jump.dataset.jump);if(target?.tagName==='DETAILS')target.open=true;for(let parent=target?.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;target?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});target?.setAttribute('tabindex','-1');target?.focus({preventScroll:true});return}if(event.target.closest('.skip-link')){event.preventDefault();document.querySelector('#main')?.focus();return}const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='start'){selectedVersion=app.querySelector('[name="version"]:checked')?.value||selectedVersion;if(state){go(state.completed?'resultados':'test');return}state={schema:AXIS_SCHEMA,version:selectedVersion,answers:{},cursor:0,completed:false};save();go('test')}
else if(action==='question-context'){const context=document.querySelector('#question-context');context.hidden=!context.hidden;b.setAttribute('aria-expanded',String(!context.hidden))}
else if(action==='auto-advance'){autoAdvance=!autoAdvance;try{localStorage.setItem('compass-auto-advance',String(autoAdvance))}catch{}b.setAttribute('aria-pressed',String(autoAdvance));b.querySelector('strong').textContent=autoAdvance?'Activado':'Desactivado';announce(autoAdvance?'Avance automático activado. Al elegir una respuesta, pasás a la siguiente pregunta.':'Avance automático desactivado. Usá Siguiente para avanzar.')}
else if(action==='previous'){state.cursor=Math.max(0,state.cursor-1);save();testScreen();document.querySelector('#main')?.focus({preventScroll:true});announce(`Pregunta ${state.cursor+1} de ${questionSet(QUESTIONS,state.version).length}`)}
else if(action==='theme'){transitionTheme(()=>{theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('compass-theme',theme)}catch{}b.innerHTML=themeGraphic();const label=theme==='dark'?'Activar modo claro':'Activar modo oscuro';b.setAttribute('aria-label',label);b.setAttribute('title',label)})}
else if(action==='reset'){shell('¿Empezar otro test?',`<p>Tu resultado o avance actual se reemplazará cuando empieces de nuevo. También podés guardar su imagen primero.</p><div class="actions">${secondary('confirm-reset','Sí, empezar de nuevo')}<a href="#${state?.completed?'resultados':'test'}" data-action="cancel-reset">Conservar mi test</a></div>`)}
else if(action==='cancel-reset'){event.preventDefault();go(state?.completed?'resultados':'test')}
else if(action==='confirm-reset'){state=null;try{localStorage.removeItem(KEY)}catch{}go('inicio')}
else if(action==='privacy')go('privacidad');
else if(action==='erase'){state=null;try{localStorage.removeItem(KEY);localStorage.removeItem(OLD_KEY);localStorage.removeItem(ARCHIVE_KEY);localStorage.removeItem(AUDIT_ARCHIVE);document.querySelector('#erase-status').textContent='Respuestas y resultado borrados.'}catch{document.querySelector('#erase-status').textContent='El navegador impidió borrar el almacenamiento. Borrá los datos de este sitio en la configuración del navegador. El perfil ya no se muestra en esta sesión.'}}
else if(action==='download'||action==='share'){try{b.disabled=true;const blob=await resultImage();if(action==='share'&&navigator.canShare?.({files:[new File([blob],'uruguay-compass.png',{type:'image/png'})]})){await navigator.share({files:[new File([blob],'uruguay-compass.png',{type:'image/png'})],title:'Mi perfil · Uruguay Compass'})}else{download(blob,'uruguay-compass.png');document.querySelector('#export-status').textContent=action==='share'?'Este navegador no permite compartir archivos directamente. Descargamos la imagen para que la compartas.':'Imagen guardada. La tarjeta incluye el alcance y los límites de la comparación.'}}catch(e){if(e.name!=='AbortError')document.querySelector('#export-status').textContent='No se pudo crear la imagen. Intentá de nuevo desde un navegador actualizado.'}finally{b.disabled=false}}
else if(action==='report-download')download(new Blob([reportText],{type:'text/plain;charset=utf-8'}),'correccion-compass.txt')});
document.addEventListener('pointermove',event=>{event.target.closest('.answers')?.classList.add('hover-ready')});
function recordAnswer(input){
 const form=document.querySelector('#question-form');if(!state||state.completed||!input.isConnected||input.form!==form)return;
 const value=Number(input.value);if(!validAnswer(value))return;
 const q=questionSet(QUESTIONS,state.version)[state.cursor];state.answers[q.id]=value;save();form.querySelector('button[type="submit"]').disabled=false;if(autoAdvance)form.requestSubmit();
}
document.addEventListener('click',event=>{if(autoAdvance&&event.target.matches('input[name="answer"]'))recordAnswer(event.target)});
document.addEventListener('change',event=>{if(event.target.name==='answer')recordAnswer(event.target);if(event.target.name==='version')selectedVersion=event.target.value});
document.addEventListener('submit',event=>{if(event.target.id==='question-form'){event.preventDefault();const qs=questionSet(QUESTIONS,state.version);if(!validAnswer(state.answers[qs[state.cursor].id]))return;if(state.migrated){if(isComplete(qs,state.answers)){state.completed=true;state.migrated=false;save();go('resultados')}else{state.cursor=qs.findIndex(q=>!validAnswer(state.answers[q.id]));save();testScreen();document.querySelector('#main')?.focus({preventScroll:true})}return}if(state.cursor===qs.length-1){if(!isComplete(qs,state.answers)){state.cursor=qs.findIndex(q=>!validAnswer(state.answers[q.id]));save();testScreen();return}state.completed=true;state.migrated=false;save();go('resultados')}else{state.cursor++;save();testScreen();document.querySelector('#main').focus({preventScroll:true});announce(`Pregunta ${state.cursor+1} de ${qs.length}`)}}if(event.target.id==='correction-form'){event.preventDefault();const fd=new FormData(event.target),subject=String(fd.get('subject')),message=String(fd.get('message')),source=String(fd.get('source'));reportText=`Ficha o pregunta: ${subject}\n\nCorrección propuesta:\n${message}\n\nFuente:\n${source}\n`;document.querySelector('#correction-preview').textContent=reportText;document.querySelector('#issue-link').href=`https://github.com/faacuaramburu/UruguayCompass/issues/new?title=${encodeURIComponent('Corrección: '+subject)}&body=${encodeURIComponent(reportText)}`;document.querySelector('#correction-output').hidden=false;document.querySelector('#correction-output').scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
document.addEventListener('input',event=>{if(!['entity-search','glossary-search'].includes(event.target.id))return;const needle=event.target.value.toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'');let count=0;for(const row of document.querySelectorAll('[data-search]')){const match=row.dataset.search.normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(needle);row.hidden=!match;if(match)count++}document.querySelector('#search-empty').hidden=count>0});
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
document.addEventListener('change',event=>{
 if(event.target.id!=='insight-reference')return;
 const entity=FIGURES.find(e=>e.id===event.target.value&&e.rankEligible);if(!entity)return;
 const details=comparisonDetails(profile(),entity.profile,ranked().axes);
 document.querySelector('#difference-content').innerHTML=renderDifferences(entity,details);
 announce(`Comparación actualizada: ${entity.name}`);
});
async function resultImage(){return createResultCard(document.querySelector('#share-preview'),{profile:profile(),axes:AXES,ranking:ranked().ranked,photos:PHOTOS})}

function refreshSpectrum({selectionOnly=false}={}){
 const host=document.querySelector('#spectrum-view'),p=profile();if(!host||!p)return;
 const active=document.activeElement,focusId=active?.dataset?.spectrumPick,wasMarker=active?.classList?.contains('spectrum-marker');
 const next=document.createElement('template');next.innerHTML=renderSpectrumView(p,FIGURES.filter(f=>f.rankEligible),spectrumState);
 // Keep the identification strip and map mounted across selections
 // to preserve keyboard focus and the browser's scroll anchor.
 host.querySelector('.spectrum-selection').replaceChildren(...next.content.querySelector('.spectrum-selection').childNodes);
 host.querySelector('.spectrum-detail').replaceWith(next.content.querySelector('.spectrum-detail'));
 if(selectionOnly){
  const selectedPoint=next.content.querySelector('.spectrum-marker.is-selected')?.dataset.spectrumPick;
  for(const marker of host.querySelectorAll('.spectrum-marker')){
   const selected=marker.dataset.spectrumPick===selectedPoint;
   marker.classList.toggle('is-selected',selected);marker.setAttribute('aria-pressed',String(selected));
  }
  for(const reference of host.querySelectorAll('.spectrum-reference'))reference.setAttribute('aria-pressed',String(reference.dataset.spectrumPick===spectrumState.selectedId));
 }else{
  host.querySelector('.spectrum-count').replaceChildren(...next.content.querySelector('.spectrum-count').childNodes);
  host.querySelector('.spectrum-graphic').replaceWith(next.content.querySelector('.spectrum-graphic'));
  host.querySelector('.spectrum-catalog').replaceWith(next.content.querySelector('.spectrum-catalog'));
 }
 if(focusId){const candidates=[...host.querySelectorAll('[data-spectrum-pick]')];const next=candidates.find(e=>e.dataset.spectrumPick===focusId&&e.classList.contains('spectrum-marker')===wasMarker);next?.focus({preventScroll:true})}
 announce(host.querySelector('.spectrum-selection').textContent);
}
document.addEventListener('input',event=>{if(event.target.id!=='spectrum-search')return;spectrumState.query=event.target.value;refreshSpectrum()});
document.addEventListener('change',event=>{if(event.target.id!=='spectrum-party')return;spectrumState.party=event.target.value;refreshSpectrum()});
document.addEventListener('click',event=>{
 const pick=event.target.closest('[data-spectrum-pick]');
 if(pick){event.preventDefault();spectrumState.selectedId=pick.dataset.spectrumPick;refreshSpectrum({selectionOnly:true});return}
 if(event.target.closest('[data-spectrum-reset]')){spectrumState.query='';spectrumState.party='all';document.querySelector('#spectrum-search').value='';document.querySelector('#spectrum-party').value='all';refreshSpectrum()}
});
document.addEventListener('keydown',event=>{const point=event.target.closest('.spectrum-marker');if(point&&['Enter',' '].includes(event.key)){event.preventDefault();spectrumState.selectedId=point.dataset.spectrumPick;refreshSpectrum({selectionOnly:true})}});

window.addEventListener('hashchange',render);render();

document.addEventListener('error',event=>{const image=event.target;if(image.tagName==='IMG'&&image.closest('.entity-media')){const box=image.closest('.entity-media');box.classList.remove('has-image');image.parentElement.hidden=true}},true);
